insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Sound', 'Sound is a phenomenon in which pressure disturbances propagate through an elastic material medium. In the context of physics, it is characterised as a mechanical wave of pressure or related quantities (e.g. displacement), whereas in physiological-psychological contexts it implies a hearing process. Though sensitivity to sound varies among all organisms, the human ear is sensitive to audio frequencies ranging from 20 Hz to 20 kHz. More broadly, acoustic waves encompass mechanical longitudinal waves in general. Examples of the significance and application of sound include music, medical imaging techniques, oral language and parts of science.', 'Wikipedia: Sound', 'https://en.wikipedia.org/w/index.php?title=Sound&oldid=1377982600', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Sound is a phenomenon in which pressure disturbances propagate through an elastic material medium. In the context of physics, it is characterised as a mechanical wave of pressure or related quantities (e.g. displacement), whereas in physiological-psychological contexts it implies a hearing process. Though sensitivity to sound varies among all organisms, the human ear is sensitive to audio frequencies ranging from 20 Hz to 20 kHz. More broadly, acoustic waves encompass mechanical longitudinal waves in general. Examples of the significance and application of sound include music, medical imaging techniques, oral language and parts of science.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Sound: Definition', 'According to the technical standard established by ANSI/ASA S1.1‑2013, the American National Standard for Acoustical Terminology, sound is defined as: "(a) Oscillation in pressure, stress, particle displacement, particle velocity, etc., propagated in a medium with internal forces (e.g., elastic or viscous), or the superposition of such propagated oscillation. This two-part definition of sound states that sound can be taken as a wave motion in an elastic medium, making it also a stimulus, or as an excitation of the hearing mechanism that results in the perception of sound, making it a sensation. While ANSI/ASA S1.1‑2013 provides the standard terminological definition of sound used in U.S. acoustics, and is one of the few major standards organisations to define the concept explicitly, physics and engineering texts often instead define sound as a kind of propagating mechanical disturbance—i.e., a wave—rather than as a vibration. Such sources typically describe sound as a perturbation in mechanical properties (e.g., pressure or particle motion) that travels through a medium and consists of medium variations (compressions and rarefactions), a formulation adopted for conceptual clarity and scientific precision.', 'Wikipedia: Sound', 'https://en.wikipedia.org/w/index.php?title=Sound&oldid=1377982600', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'According to the technical standard established by ANSI/ASA S1.1‑2013, the American National Standard for Acoustical Terminology, sound is defined as: "(a) Oscillation in pressure, stress, particle displacement, particle velocity, etc., propagated in a medium with internal forces (e.g., elastic or viscous), or the superposition of such propagated oscillation. This two-part definition of sound states that sound can be taken as a wave motion in an elastic medium, making it also a stimulus, or as an excitation of the hearing mechanism that results in the perception of sound, making it a sensation. While ANSI/ASA S1.1‑2013 provides the standard terminological definition of sound used in U.S. acoustics, and is one of the few major standards organisations to define the concept explicitly, physics and engineering texts often instead define sound as a kind of propagating mechanical disturbance—i.e., a wave—rather than as a vibration. Such sources typically describe sound as a perturbation in mechanical properties (e.g., pressure or particle motion) that travels through a medium and consists of medium variations (compressions and rarefactions), a formulation adopted for conceptual clarity and scientific precision.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Sound: Acoustics', 'Acoustics is the interdisciplinary scientific study of mechanical waves, vibrations, sound, ultrasound, and infrasound in gaseous, liquid, or solid media. A scientist who works in the field of acoustics is called an acoustician, while an individual specialising in acoustical engineering may be referred to as an acoustical engineer. An audio engineer, by contrast, is concerned with the recording, manipulation, mixing, and reproduction of sound. Applications of acoustics are found in many areas of modern society. Subdisciplines include aeroacoustics, audio signal processing, architectural acoustics, bioacoustics, electroacoustics, environmental noise, musical acoustics, noise control, psychoacoustics, speech, ultrasound, underwater acoustics, and vibration.', 'Wikipedia: Sound', 'https://en.wikipedia.org/w/index.php?title=Sound&oldid=1377982600', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Acoustics is the interdisciplinary scientific study of mechanical waves, vibrations, sound, ultrasound, and infrasound in gaseous, liquid, or solid media. A scientist who works in the field of acoustics is called an acoustician, while an individual specialising in acoustical engineering may be referred to as an acoustical engineer. An audio engineer, by contrast, is concerned with the recording, manipulation, mixing, and reproduction of sound. Applications of acoustics are found in many areas of modern society. Subdisciplines include aeroacoustics, audio signal processing, architectural acoustics, bioacoustics, electroacoustics, environmental noise, musical acoustics, noise control, psychoacoustics, speech, ultrasound, underwater acoustics, and vibration.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Sound: Physics', 'Sound travels as a mechanical wave through a medium (e.g. water, crystals, air). Sound waves are generated by a sound source, such as a vibrating diaphragm of a loudspeaker. As the sound source vibrates the surrounding medium, mechanical disturbances propagate away from the source at the local speed of sound, thus resulting in a sound wave. At a fixed distance from the source, the pressure, velocity, and displacement of the medium''s particles vary in time. At an instant in time, the pressure, velocity, and displacement vary spatially. The particles of the medium do not travel with the sound wave; instead, the disturbance and its mechanical energy propagate through the medium. Though intuitively expectable for solids, this also applies for liquids and gases. The matter that supports the transmission of a sound is named the transmission medium. Media may be any form of matter, whether solids, liquids, gases or plasmas. However, sound cannot propagate through a vacuum because there is no medium to support mechanical disturbances. A complicated relationship between the density and pressure of the medium. This relationship, also affected by temperature, determines the speed of sound within the medium.', 'Wikipedia: Sound', 'https://en.wikipedia.org/w/index.php?title=Sound&oldid=1377982600', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Sound travels as a mechanical wave through a medium (e.g. water, crystals, air). Sound waves are generated by a sound source, such as a vibrating diaphragm of a loudspeaker. As the sound source vibrates the surrounding medium, mechanical disturbances propagate away from the source at the local speed of sound, thus resulting in a sound wave. At a fixed distance from the source, the pressure, velocity, and displacement of the medium''s particles vary in time. At an instant in time, the pressure, velocity, and displacement vary spatially. The particles of the medium do not travel with the sound wave; instead, the disturbance and its mechanical energy propagate through the medium. Though intuitively expectable for solids, this also applies for liquids and gases. The matter that supports the transmission of a sound is named the transmission medium. Media may be any form of matter, whether solids, liquids, gases or plasmas. However, sound cannot propagate through a vacuum because there is no medium to support mechanical disturbances. A complicated relationship between the density and pressure of the medium. This relationship, also affected by temperature, determines the speed of sound within the medium.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Sound: Physics', 'Motion of the medium itself. If the medium is moving, this movement may increase or decrease the absolute speed of the sound wave depending on the direction of the movement. For example, sound moving through wind will have its speed of propagation increased by the speed of the wind if the sound and wind are moving in the same direction. If the sound and wind are moving in opposite directions, the speed of the sound wave will be decreased by the speed of the wind. The viscosity of the medium. Medium viscosity determines the rate at which sound is attenuated. For many media, such as air or water, attenuation due to viscosity is negligible. Theoretical work indicates that sound waves carry an extremely small effective gravitational mass. This mass arises from nonlinear corrections to the stress–energy of the wave, and implies that sound waves both respond to gravity and generate a very weak gravitational field of their own. For ordinary equations of state, the effective mass is negative, meaning that sound waves in such media act as if they carry a tiny negative gravitational mass. The effect is extremely small because it appears only at nonlinear order in the equations governing wave motion.', 'Wikipedia: Sound', 'https://en.wikipedia.org/w/index.php?title=Sound&oldid=1377982600', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Motion of the medium itself. If the medium is moving, this movement may increase or decrease the absolute speed of the sound wave depending on the direction of the movement. For example, sound moving through wind will have its speed of propagation increased by the speed of the wind if the sound and wind are moving in the same direction. If the sound and wind are moving in opposite directions, the speed of the sound wave will be decreased by the speed of the wind. The viscosity of the medium. Medium viscosity determines the rate at which sound is attenuated. For many media, such as air or water, attenuation due to viscosity is negligible. Theoretical work indicates that sound waves carry an extremely small effective gravitational mass. This mass arises from nonlinear corrections to the stress–energy of the wave, and implies that sound waves both respond to gravity and generate a very weak gravitational field of their own. For ordinary equations of state, the effective mass is negative, meaning that sound waves in such media act as if they carry a tiny negative gravitational mass. The effect is extremely small because it appears only at nonlinear order in the equations governing wave motion.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Sound: Waves', 'Sound waves exhibit behaviours such as reflection, transmission, refraction, diffraction, absorption, and attenuation. When sound is moving through a non‑homogeneous medium, it may be refracted (either dispersed or focused). Sound is transmitted through fluids (e.g. gases, plasmas, and liquids) as longitudinal waves, also called compression waves. Through solids, however, sound can be transmitted as both longitudinal waves and transverse waves. Longitudinal sound waves are waves of alternating pressure deviations from the equilibrium pressure, causing local regions of compression and rarefaction, while transverse waves (in solids) are waves of alternating shear stress perpendicular to the direction of propagation. Unlike longitudinal sound waves, transverse sound waves have the property of polarisation. Sound waves may be viewed using parabolic mirrors and objects that produce sound. The energy carried by a periodic sound wave alternates between the potential energy of the extra compression (in the case of longitudinal waves) or lateral displacement strain (in the case of transverse waves) of the matter, and the kinetic energy of the particles'' displacement velocity in the medium. Although sound transmission involves many physical processes, the signal received at a point (such as a microphone or the ear) can be fully described as a time‑varying pressure. This pressure‑versus‑time waveform provides a complete representation of any sound or audio signal detected at that location.', 'Wikipedia: Sound', 'https://en.wikipedia.org/w/index.php?title=Sound&oldid=1377982600', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Sound waves exhibit behaviours such as reflection, transmission, refraction, diffraction, absorption, and attenuation. When sound is moving through a non‑homogeneous medium, it may be refracted (either dispersed or focused). Sound is transmitted through fluids (e.g. gases, plasmas, and liquids) as longitudinal waves, also called compression waves. Through solids, however, sound can be transmitted as both longitudinal waves and transverse waves. Longitudinal sound waves are waves of alternating pressure deviations from the equilibrium pressure, causing local regions of compression and rarefaction, while transverse waves (in solids) are waves of alternating shear stress perpendicular to the direction of propagation. Unlike longitudinal sound waves, transverse sound waves have the property of polarisation. Sound waves may be viewed using parabolic mirrors and objects that produce sound. The energy carried by a periodic sound wave alternates between the potential energy of the extra compression (in the case of longitudinal waves) or lateral displacement strain (in the case of transverse waves) of the matter, and the kinetic energy of the particles'' displacement velocity in the medium. Although sound transmission involves many physical processes, the signal received at a point (such as a microphone or the ear) can be fully described as a time‑varying pressure. This pressure‑versus‑time waveform provides a complete representation of any sound or audio signal detected at that location.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Sound: Waves', 'Sound waves are often simplified as sinusoidal plane waves, which are characterized by these generic properties: Sometimes speed and direction are combined as a velocity vector; wave number and direction are combined as a wave vector. To analyse audio, a complicated waveform—such as the one shown on the right—can be represented as a linear combination of sinusoidal components of different frequencies, amplitudes, and phases.', 'Wikipedia: Sound', 'https://en.wikipedia.org/w/index.php?title=Sound&oldid=1377982600', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Sound waves are often simplified as sinusoidal plane waves, which are characterized by these generic properties: Sometimes speed and direction are combined as a velocity vector; wave number and direction are combined as a wave vector. To analyse audio, a complicated waveform—such as the one shown on the right—can be represented as a linear combination of sinusoidal components of different frequencies, amplitudes, and phases.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Sound: Speed', 'The speed of sound depends on the medium the waves pass through, and is a fundamental property of the material. The first significant effort towards measurement of the speed of sound was made by Isaac Newton. He believed the speed of sound in a particular substance was equal to the square root of the pressure acting on it divided by its density: This was later disproven and the French mathematician Laplace corrected the formula by deducing that the phenomenon of sound travelling is not isothermal, as believed by Newton, but adiabatic. He added another factor to the equation—gamma—and multiplied which is also known as the Newton–Laplace equation. In this equation, K is the elastic bulk modulus, c is the velocity of sound, and is the density. Thus, the speed of sound is proportional to the square root of the ratio of the bulk modulus of the medium to its density.', 'Wikipedia: Sound', 'https://en.wikipedia.org/w/index.php?title=Sound&oldid=1377982600', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'The speed of sound depends on the medium the waves pass through, and is a fundamental property of the material. The first significant effort towards measurement of the speed of sound was made by Isaac Newton. He believed the speed of sound in a particular substance was equal to the square root of the pressure acting on it divided by its density: This was later disproven and the French mathematician Laplace corrected the formula by deducing that the phenomenon of sound travelling is not isothermal, as believed by Newton, but adiabatic. He added another factor to the equation—gamma—and multiplied which is also known as the Newton–Laplace equation. In this equation, K is the elastic bulk modulus, c is the velocity of sound, and is the density. Thus, the speed of sound is proportional to the square root of the ratio of the bulk modulus of the medium to its density.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Doppler effect', 'The Doppler effect (also Doppler shift) is the change in the frequency or, equivalently, the period of a wave in relation to an observer who is moving relative to the source of the wave. It is named after Christian Doppler, who described the phenomenon in 1842. A common example of a Doppler shift is the change of pitch heard when a vehicle approaches and recedes from an observer. Compared to the emitted sound, the received sound has a higher pitch during the approach, identical at the instant of passing by, and lower pitch during the recession. When the source of the sound wave is moving towards the observer, each successive cycle of the wave is emitted from a position closer to the observer than the previous cycle. Hence, from the observer''s perspective, the period or time between cycles is reduced, meaning the frequency is increased. Conversely, if the source of the sound wave is moving away from the observer, each cycle of the wave is emitted from a position farther from the observer than the previous cycle, so the period or time between successive cycles is increased, thus reducing the frequency.', 'Wikipedia: Doppler effect', 'https://en.wikipedia.org/w/index.php?title=Doppler_effect&oldid=1380971626', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'The Doppler effect (also Doppler shift) is the change in the frequency or, equivalently, the period of a wave in relation to an observer who is moving relative to the source of the wave. It is named after Christian Doppler, who described the phenomenon in 1842. A common example of a Doppler shift is the change of pitch heard when a vehicle approaches and recedes from an observer. Compared to the emitted sound, the received sound has a higher pitch during the approach, identical at the instant of passing by, and lower pitch during the recession. When the source of the sound wave is moving towards the observer, each successive cycle of the wave is emitted from a position closer to the observer than the previous cycle. Hence, from the observer''s perspective, the period or time between cycles is reduced, meaning the frequency is increased. Conversely, if the source of the sound wave is moving away from the observer, each cycle of the wave is emitted from a position farther from the observer than the previous cycle, so the period or time between successive cycles is increased, thus reducing the frequency.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Doppler effect', 'For waves propagating in a vacuum, as is possible for electromagnetic waves or gravitational waves, only the relative velocity between the observer and the source needs to be considered. For waves that propagate in a medium, such as sound waves, the velocity of the observer and of the source are relative to the medium in which the waves are transmitted. The total Doppler effect in such cases may therefore result from motion of the source, motion of the observer, motion of the medium, or any combination thereof.', 'Wikipedia: Doppler effect', 'https://en.wikipedia.org/w/index.php?title=Doppler_effect&oldid=1380971626', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'For waves propagating in a vacuum, as is possible for electromagnetic waves or gravitational waves, only the relative velocity between the observer and the source needs to be considered. For waves that propagate in a medium, such as sound waves, the velocity of the observer and of the source are relative to the medium in which the waves are transmitted. The total Doppler effect in such cases may therefore result from motion of the source, motion of the observer, motion of the medium, or any combination thereof.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Doppler effect: General', 'is the speed of the wave receiver relative to the medium. In the formula, if the receiver is moving towards the source, and subtracted if moving away; is the speed of the wave source relative to the medium. In the formula, if the source is moving towards the receiver, and added if moving away. here are not vectors as velocities, but their magnitudes as speeds. This relationship predicts that the observed frequency by the receiver will decrease if the distance between the source and receiver is increasing. Note that the speed of the wave is determined by the medium, not by the speed of the source.', 'Wikipedia: Doppler effect', 'https://en.wikipedia.org/w/index.php?title=Doppler_effect&oldid=1380971626', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'is the speed of the wave receiver relative to the medium. In the formula, if the receiver is moving towards the source, and subtracted if moving away; is the speed of the wave source relative to the medium. In the formula, if the source is moving towards the receiver, and added if moving away. here are not vectors as velocities, but their magnitudes as speeds. This relationship predicts that the observed frequency by the receiver will decrease if the distance between the source and receiver is increasing. Note that the speed of the wave is determined by the medium, not by the speed of the source.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Doppler effect: General', 'If the source approaches the observer at an angle (but still with a constant speed), the observed frequency that is first heard is higher than the object''s emitted frequency. Thereafter, there is a monotonic decrease in the observed frequency as it gets closer to the observer, through equality when it is coming from a direction perpendicular to the relative motion (and was emitted at the point of closest approach; but when the wave is received, the source and observer will no longer be at their closest), and a continued monotonic decrease as it recedes from the observer. When the observer is very close to the path of the object, the transition from high to low frequency is very abrupt. When the observer is far from the path of the object, the transition from high to low frequency is gradual.', 'Wikipedia: Doppler effect', 'https://en.wikipedia.org/w/index.php?title=Doppler_effect&oldid=1380971626', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'If the source approaches the observer at an angle (but still with a constant speed), the observed frequency that is first heard is higher than the object''s emitted frequency. Thereafter, there is a monotonic decrease in the observed frequency as it gets closer to the observer, through equality when it is coming from a direction perpendicular to the relative motion (and was emitted at the point of closest approach; but when the wave is received, the source and observer will no longer be at their closest), and a continued monotonic decrease as it recedes from the observer. When the observer is very close to the path of the object, the transition from high to low frequency is very abrupt. When the observer is far from the path of the object, the transition from high to low frequency is gradual.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Doppler effect: Consequences', 'Assuming a stationary observer and a wave source moving towards the observer at (or exceeding) the speed of the wave, the Doppler equation predicts an infinite (or negative) frequency as from the observer''s perspective. Thus, the Doppler equation is inapplicable for such cases. If the wave is a sound wave and the sound source is moving faster than the speed of sound, the resulting shock wave creates a sonic boom. Lord Rayleigh predicted the following effect in his classic book on sound: if the observer were moving from the (stationary) source at twice the speed of sound, a musical piece previously emitted by that source would be heard in correct tempo and pitch, but as if played backwards.', 'Wikipedia: Doppler effect', 'https://en.wikipedia.org/w/index.php?title=Doppler_effect&oldid=1380971626', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Assuming a stationary observer and a wave source moving towards the observer at (or exceeding) the speed of the wave, the Doppler equation predicts an infinite (or negative) frequency as from the observer''s perspective. Thus, the Doppler equation is inapplicable for such cases. If the wave is a sound wave and the sound source is moving faster than the speed of sound, the resulting shock wave creates a sonic boom. Lord Rayleigh predicted the following effect in his classic book on sound: if the observer were moving from the (stationary) source at twice the speed of sound, a musical piece previously emitted by that source would be heard in correct tempo and pitch, but as if played backwards.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Doppler effect: Sirens', 'A siren on a passing emergency vehicle will start out higher than its stationary pitch, slide down as it passes, and continue lower than its stationary pitch as it recedes from the observer. Astronomer John Dobson explained the effect thus: In other words, if the siren approached the observer directly, the pitch would remain constant, at a higher than stationary pitch, until the vehicle hit them, and then immediately jump to a new lower pitch. Because the vehicle passes by the observer, the radial speed does not remain constant, but instead varies as a function of the angle between his line of sight and the siren''s velocity: is the angle between the object''s forward velocity and the line of sight from the object to the observer.', 'Wikipedia: Doppler effect', 'https://en.wikipedia.org/w/index.php?title=Doppler_effect&oldid=1380971626', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'A siren on a passing emergency vehicle will start out higher than its stationary pitch, slide down as it passes, and continue lower than its stationary pitch as it recedes from the observer. Astronomer John Dobson explained the effect thus: In other words, if the siren approached the observer directly, the pitch would remain constant, at a higher than stationary pitch, until the vehicle hit them, and then immediately jump to a new lower pitch. Because the vehicle passes by the observer, the radial speed does not remain constant, but instead varies as a function of the angle between his line of sight and the siren''s velocity: is the angle between the object''s forward velocity and the line of sight from the object to the observer.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Doppler effect: Astronomy', 'The Doppler effect for electromagnetic waves such as light is of widespread use in astronomy to measure the speed at which stars and galaxies are approaching or receding from us, resulting in so called blueshift or redshift, respectively. This may be used to detect if an apparently single star is, in reality, a close binary, to measure the rotational speed of stars and galaxies, or to detect exoplanets. This effect typically happens on a very small scale; there would not be a noticeable difference in visible light to the unaided eye. The use of the Doppler effect in astronomy depends on knowledge of precise frequencies of discrete lines in the spectra of stars. The relationship between the expansion of the universe and the Doppler effect is not simply caused by the source moving away from the observer. In cosmology, the redshift of expansion is considered separate from redshifts due to gravity or Doppler motion. Distant galaxies also exhibit peculiar motion distinct from their cosmological recession speeds. If redshifts are used to determine distances in accordance with Hubble''s law, then these peculiar motions give rise to redshift-space distortions.', 'Wikipedia: Doppler effect', 'https://en.wikipedia.org/w/index.php?title=Doppler_effect&oldid=1380971626', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'The Doppler effect for electromagnetic waves such as light is of widespread use in astronomy to measure the speed at which stars and galaxies are approaching or receding from us, resulting in so called blueshift or redshift, respectively. This may be used to detect if an apparently single star is, in reality, a close binary, to measure the rotational speed of stars and galaxies, or to detect exoplanets. This effect typically happens on a very small scale; there would not be a noticeable difference in visible light to the unaided eye. The use of the Doppler effect in astronomy depends on knowledge of precise frequencies of discrete lines in the spectra of stars. The relationship between the expansion of the universe and the Doppler effect is not simply caused by the source moving away from the observer. In cosmology, the redshift of expansion is considered separate from redshifts due to gravity or Doppler motion. Distant galaxies also exhibit peculiar motion distinct from their cosmological recession speeds. If redshifts are used to determine distances in accordance with Hubble''s law, then these peculiar motions give rise to redshift-space distortions.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Doppler effect: Radar', 'The Doppler effect is used in some types of radar to measure the velocity of detected objects. A radar beam is fired at a moving target – e.g. a motor car, as police use radar to detect speeding motorists – as it approaches to or recedes from the radar source. In the case of a car moving away from the source, each successive radar wave has to travel farther to reach the car, before being reflected and re-detected near the source. As each wave has to move farther, the gaps between the wave crests increase, increasing the wavelength of the radiation returning to the radar. In the opposite case, when the radar beam is fired at the moving car as it approaches, each successive wave travels a lesser distance, decreasing the wavelength. In either situation, calculations from the Doppler effect accurately determine the car''s speed. For instance, a police radar operating at 24.15 GHz (K-band) detecting a vehicle traveling at 30 m/s (108 km/h) will measure a Doppler shift of approximately 4.83 kHz, a change easily detected by modern digital signal processing. Moreover, the proximity fuze, developed during World War II, relies upon Doppler radar to detonate explosives at the correct time, height, distance, etc.', 'Wikipedia: Doppler effect', 'https://en.wikipedia.org/w/index.php?title=Doppler_effect&oldid=1380971626', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'The Doppler effect is used in some types of radar to measure the velocity of detected objects. A radar beam is fired at a moving target – e.g. a motor car, as police use radar to detect speeding motorists – as it approaches to or recedes from the radar source. In the case of a car moving away from the source, each successive radar wave has to travel farther to reach the car, before being reflected and re-detected near the source. As each wave has to move farther, the gaps between the wave crests increase, increasing the wavelength of the radiation returning to the radar. In the opposite case, when the radar beam is fired at the moving car as it approaches, each successive wave travels a lesser distance, decreasing the wavelength. In either situation, calculations from the Doppler effect accurately determine the car''s speed. For instance, a police radar operating at 24.15 GHz (K-band) detecting a vehicle traveling at 30 m/s (108 km/h) will measure a Doppler shift of approximately 4.83 kHz, a change easily detected by modern digital signal processing. Moreover, the proximity fuze, developed during World War II, relies upon Doppler radar to detonate explosives at the correct time, height, distance, etc.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Electromagnetic spectrum', 'The electromagnetic spectrum is the full range of electromagnetic radiation, organized by frequency or wavelength. The spectrum is divided into separate bands, with different names for the electromagnetic waves within each band. From low to high frequency these are: radio waves, microwaves, infrared, visible light, ultraviolet, X-rays, and gamma rays. The electromagnetic waves in each of these bands have different characteristics, such as how they are produced, how they interact with matter, and their practical applications. Radio waves, at the low-frequency end of the spectrum, have the lowest photon energy and the longest wavelengths—thousands of kilometers, or more. They can be emitted and received by antennas, and pass through the atmosphere, foliage, and most building materials. Gamma rays, at the high-frequency end of the spectrum, have the highest photon energies and the shortest wavelengths—much smaller than an atomic nucleus. Gamma rays, X-rays, and extreme ultraviolet rays are called ionizing radiation because their high photon energy is able to ionize atoms, causing chemical reactions. Longer-wavelength radiation such as visible light is non-ionizing; the photons do not have sufficient energy to ionize atoms.', 'Wikipedia: Electromagnetic spectrum', 'https://en.wikipedia.org/w/index.php?title=Electromagnetic_spectrum&oldid=1381395720', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'The electromagnetic spectrum is the full range of electromagnetic radiation, organized by frequency or wavelength. The spectrum is divided into separate bands, with different names for the electromagnetic waves within each band. From low to high frequency these are: radio waves, microwaves, infrared, visible light, ultraviolet, X-rays, and gamma rays. The electromagnetic waves in each of these bands have different characteristics, such as how they are produced, how they interact with matter, and their practical applications. Radio waves, at the low-frequency end of the spectrum, have the lowest photon energy and the longest wavelengths—thousands of kilometers, or more. They can be emitted and received by antennas, and pass through the atmosphere, foliage, and most building materials. Gamma rays, at the high-frequency end of the spectrum, have the highest photon energies and the shortest wavelengths—much smaller than an atomic nucleus. Gamma rays, X-rays, and extreme ultraviolet rays are called ionizing radiation because their high photon energy is able to ionize atoms, causing chemical reactions. Longer-wavelength radiation such as visible light is non-ionizing; the photons do not have sufficient energy to ionize atoms.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Electromagnetic spectrum', 'Throughout most of the electromagnetic spectrum, spectroscopy can be used to separate waves of different frequencies, so that the intensity of the radiation can be measured as a function of frequency or wavelength. Spectroscopy is used to study the interactions of electromagnetic waves with matter.', 'Wikipedia: Electromagnetic spectrum', 'https://en.wikipedia.org/w/index.php?title=Electromagnetic_spectrum&oldid=1381395720', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Throughout most of the electromagnetic spectrum, spectroscopy can be used to separate waves of different frequencies, so that the intensity of the radiation can be measured as a function of frequency or wavelength. Spectroscopy is used to study the interactions of electromagnetic waves with matter.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Electromagnetic spectrum: History and discovery', 'In 1672 Isaac Newton submitted his first paper to the Royal Society, describing the range of colours that white light could be split into with a prism using the term spectrum. Newton showed that these colours were intrinsic to light and could be combined to recreate white light. Around 1801, Thomas Young performed a number of interference experiments that played a major role in the acceptance of the wave theory of light. In 1800, William Herschel discovered infrared radiation. He was studying the temperature of different colours by moving a thermometer through light split by a prism. He noticed that the highest temperature was beyond red. He theorized that this temperature change was due to "calorific rays", a type of light ray that could not be seen. The next year, Johann Ritter, working at the other end of the spectrum, noticed what he called "chemical rays" (invisible light rays that induced certain chemical reactions). These behaved similarly to visible violet light rays, but were beyond them in the spectrum. They were later renamed ultraviolet radiation.', 'Wikipedia: Electromagnetic spectrum', 'https://en.wikipedia.org/w/index.php?title=Electromagnetic_spectrum&oldid=1381395720', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'In 1672 Isaac Newton submitted his first paper to the Royal Society, describing the range of colours that white light could be split into with a prism using the term spectrum. Newton showed that these colours were intrinsic to light and could be combined to recreate white light. Around 1801, Thomas Young performed a number of interference experiments that played a major role in the acceptance of the wave theory of light. In 1800, William Herschel discovered infrared radiation. He was studying the temperature of different colours by moving a thermometer through light split by a prism. He noticed that the highest temperature was beyond red. He theorized that this temperature change was due to "calorific rays", a type of light ray that could not be seen. The next year, Johann Ritter, working at the other end of the spectrum, noticed what he called "chemical rays" (invisible light rays that induced certain chemical reactions). These behaved similarly to visible violet light rays, but were beyond them in the spectrum. They were later renamed ultraviolet radiation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Electromagnetic spectrum: History and discovery', 'The study of electromagnetism began in 1820 when Hans Christian Ørsted discovered that electric currents produce magnetic fields (Oersted''s law). Light was first linked to electromagnetism in 1845, when Michael Faraday noticed that the polarization of light traveling through a transparent material responded to a magnetic field (see Faraday effect). During the 1860s, James Clerk Maxwell developed four partial differential equations (Maxwell''s equations) for the electromagnetic field. Two of these equations predicted the possibility and behavior of waves in the field. Analyzing the speed of these theoretical waves, Maxwell realized that they must travel at a speed that was about the known speed of light. This startling coincidence in value led Maxwell to make the inference that light itself is a type of electromagnetic wave. Maxwell''s equations predicted an infinite range of frequencies of electromagnetic waves, all traveling at the speed of light. This was the first indication of the existence of the entire electromagnetic spectrum.', 'Wikipedia: Electromagnetic spectrum', 'https://en.wikipedia.org/w/index.php?title=Electromagnetic_spectrum&oldid=1381395720', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'The study of electromagnetism began in 1820 when Hans Christian Ørsted discovered that electric currents produce magnetic fields (Oersted''s law). Light was first linked to electromagnetism in 1845, when Michael Faraday noticed that the polarization of light traveling through a transparent material responded to a magnetic field (see Faraday effect). During the 1860s, James Clerk Maxwell developed four partial differential equations (Maxwell''s equations) for the electromagnetic field. Two of these equations predicted the possibility and behavior of waves in the field. Analyzing the speed of these theoretical waves, Maxwell realized that they must travel at a speed that was about the known speed of light. This startling coincidence in value led Maxwell to make the inference that light itself is a type of electromagnetic wave. Maxwell''s equations predicted an infinite range of frequencies of electromagnetic waves, all traveling at the speed of light. This was the first indication of the existence of the entire electromagnetic spectrum.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Electromagnetic spectrum: History and discovery', 'Maxwell''s predicted waves included waves at very low frequencies compared to infrared, which he hypothesized might be created by oscillating charges. Attempting to prove Maxwell''s equations and detect such low frequency electromagnetic radiation, in 1886, the physicist Heinrich Hertz built an apparatus to generate and detect what are now called radio waves. Hertz found the waves and was able to infer (by measuring their wavelength and multiplying it by their frequency) that they traveled at the speed of light. Hertz also demonstrated that the new radiation could be both reflected and refracted by various dielectric media, in the same manner as light. For example, Hertz was able to focus the waves using a lens made of tree resin. In a later experiment, Hertz similarly produced and measured the properties of microwaves. These new types of waves paved the way for inventions such as the wireless telegraph and the radio. In 1895, Wilhelm Röntgen noticed a new type of radiation emitted during an experiment with an evacuated tube subjected to a high voltage. He called this radiation "x-rays" and found that they were able to travel through parts of the human body but were reflected or stopped by denser matter such as bones. Before long, many uses were found for this radiography.', 'Wikipedia: Electromagnetic spectrum', 'https://en.wikipedia.org/w/index.php?title=Electromagnetic_spectrum&oldid=1381395720', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Maxwell''s predicted waves included waves at very low frequencies compared to infrared, which he hypothesized might be created by oscillating charges. Attempting to prove Maxwell''s equations and detect such low frequency electromagnetic radiation, in 1886, the physicist Heinrich Hertz built an apparatus to generate and detect what are now called radio waves. Hertz found the waves and was able to infer (by measuring their wavelength and multiplying it by their frequency) that they traveled at the speed of light. Hertz also demonstrated that the new radiation could be both reflected and refracted by various dielectric media, in the same manner as light. For example, Hertz was able to focus the waves using a lens made of tree resin. In a later experiment, Hertz similarly produced and measured the properties of microwaves. These new types of waves paved the way for inventions such as the wireless telegraph and the radio. In 1895, Wilhelm Röntgen noticed a new type of radiation emitted during an experiment with an evacuated tube subjected to a high voltage. He called this radiation "x-rays" and found that they were able to travel through parts of the human body but were reflected or stopped by denser matter such as bones. Before long, many uses were found for this radiography.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Electromagnetic spectrum: History and discovery', 'The last portion of the electromagnetic spectrum was filled in with the discovery of gamma rays. In 1900, Paul Villard was studying the radioactive emissions of radium when he identified a new type of radiation that he at first thought consisted of particles similar to known alpha and beta particles, but with the power of being far more penetrating than either. However, in 1910, British physicist William Henry Bragg demonstrated that gamma rays are electromagnetic radiation, not particles, and in 1914, Ernest Rutherford (who had named them gamma rays in 1903 when he realized that they were fundamentally different from charged alpha and beta particles) and Edward Andrade measured their wavelengths, and found that gamma rays were similar to X-rays, but with shorter wavelengths. The wave-particle debate was rekindled in 1901 when Max Planck discovered that light is absorbed only in discrete "quanta", now called photons, implying that light has a particle nature. This idea was made explicit by Albert Einstein in 1905, but never accepted by Planck and many other contemporaries. The modern position of science is that electromagnetic radiation has both a wave and a particle nature, the wave-particle duality. The contradictions arising from this position are still being debated by scientists and philosophers.', 'Wikipedia: Electromagnetic spectrum', 'https://en.wikipedia.org/w/index.php?title=Electromagnetic_spectrum&oldid=1381395720', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'The last portion of the electromagnetic spectrum was filled in with the discovery of gamma rays. In 1900, Paul Villard was studying the radioactive emissions of radium when he identified a new type of radiation that he at first thought consisted of particles similar to known alpha and beta particles, but with the power of being far more penetrating than either. However, in 1910, British physicist William Henry Bragg demonstrated that gamma rays are electromagnetic radiation, not particles, and in 1914, Ernest Rutherford (who had named them gamma rays in 1903 when he realized that they were fundamentally different from charged alpha and beta particles) and Edward Andrade measured their wavelengths, and found that gamma rays were similar to X-rays, but with shorter wavelengths. The wave-particle debate was rekindled in 1901 when Max Planck discovered that light is absorbed only in discrete "quanta", now called photons, implying that light has a particle nature. This idea was made explicit by Albert Einstein in 1905, but never accepted by Planck and many other contemporaries. The modern position of science is that electromagnetic radiation has both a wave and a particle nature, the wave-particle duality. The contradictions arising from this position are still being debated by scientists and philosophers.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Electromagnetic spectrum: Range', 'Electromagnetic waves are typically described by any of the following three physical properties: the frequency f, wavelength λ, or photon energy E. Frequencies observed in astronomy range from 2.4×1023 Hz (1 GeV gamma rays) down to the local plasma frequency of the ionized interstellar medium (~1 kHz). Wavelength is inversely proportional to the wave frequency, so gamma rays have very short wavelengths that are fractions of the size of atoms, whereas wavelengths on the opposite end of the spectrum can be indefinitely long. Photon energy is directly proportional to the wave frequency, so gamma ray photons have the highest energy (around a billion electron volts), while radio wave photons have very low energy (around a femtoelectronvolt). These relations are illustrated by the following equations: Whenever electromagnetic waves travel in a medium with matter, their wavelength is decreased. Wavelengths of electromagnetic radiation, whatever medium they are traveling through, are usually quoted in terms of the vacuum wavelength, although this is not always explicitly stated. Generally, electromagnetic radiation is classified by wavelength into radio wave, microwave, infrared, visible light, ultraviolet, X-rays and gamma rays. The behavior of EM radiation depends on its wavelength. When EM radiation interacts with single atoms and molecules, its behavior also depends on the amount of energy per quantum (photon) it carries.', 'Wikipedia: Electromagnetic spectrum', 'https://en.wikipedia.org/w/index.php?title=Electromagnetic_spectrum&oldid=1381395720', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Electromagnetic waves are typically described by any of the following three physical properties: the frequency f, wavelength λ, or photon energy E. Frequencies observed in astronomy range from 2.4×1023 Hz (1 GeV gamma rays) down to the local plasma frequency of the ionized interstellar medium (~1 kHz). Wavelength is inversely proportional to the wave frequency, so gamma rays have very short wavelengths that are fractions of the size of atoms, whereas wavelengths on the opposite end of the spectrum can be indefinitely long. Photon energy is directly proportional to the wave frequency, so gamma ray photons have the highest energy (around a billion electron volts), while radio wave photons have very low energy (around a femtoelectronvolt). These relations are illustrated by the following equations: Whenever electromagnetic waves travel in a medium with matter, their wavelength is decreased. Wavelengths of electromagnetic radiation, whatever medium they are traveling through, are usually quoted in terms of the vacuum wavelength, although this is not always explicitly stated. Generally, electromagnetic radiation is classified by wavelength into radio wave, microwave, infrared, visible light, ultraviolet, X-rays and gamma rays. The behavior of EM radiation depends on its wavelength. When EM radiation interacts with single atoms and molecules, its behavior also depends on the amount of energy per quantum (photon) it carries.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Electromagnetic spectrum: Range', 'Spectroscopy can detect a much wider region of the EM spectrum than the visible wavelength range of 400 nm to 700 nm in a vacuum. A common laboratory spectroscope can detect wavelengths from 2 nm to 2500 nm. Detailed information about the physical properties of objects, gases, or even stars can be obtained from this type of device. Spectroscopes are widely used in astrophysics. For example, many hydrogen atoms emit a radio wave photon that has a wavelength of 21.12 cm. Also, frequencies of 30 Hz and below can be produced by and are important in the study of certain stellar nebulae and frequencies as high as 2.9×1027 Hz have been detected from astrophysical sources.', 'Wikipedia: Electromagnetic spectrum', 'https://en.wikipedia.org/w/index.php?title=Electromagnetic_spectrum&oldid=1381395720', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Spectroscopy can detect a much wider region of the EM spectrum than the visible wavelength range of 400 nm to 700 nm in a vacuum. A common laboratory spectroscope can detect wavelengths from 2 nm to 2500 nm. Detailed information about the physical properties of objects, gases, or even stars can be obtained from this type of device. Spectroscopes are widely used in astrophysics. For example, many hydrogen atoms emit a radio wave photon that has a wavelength of 21.12 cm. Also, frequencies of 30 Hz and below can be produced by and are important in the study of certain stellar nebulae and frequencies as high as 2.9×1027 Hz have been detected from astrophysical sources.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Refraction', 'In physics, refraction is the redirection of a wave as it passes from one medium to another. The redirection can be caused by the wave''s change in speed or by a change in the medium. Refraction of light is the most commonly observed phenomenon, but other waves such as sound waves and water waves also experience refraction. How much a wave is refracted is determined by the change in wave speed and the initial direction of wave propagation relative to the direction of change in speed. Optical prisms and lenses use refraction to redirect light, as does the human eye. The refractive index of materials varies with the wavelength of light, and thus the angle of the refraction also varies correspondingly. This is called dispersion and allows certain prisms and raindrops in rainbows to divide white light into its constituent spectral colors.', 'Wikipedia: Refraction', 'https://en.wikipedia.org/w/index.php?title=Refraction&oldid=1372828267', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'In physics, refraction is the redirection of a wave as it passes from one medium to another. The redirection can be caused by the wave''s change in speed or by a change in the medium. Refraction of light is the most commonly observed phenomenon, but other waves such as sound waves and water waves also experience refraction. How much a wave is refracted is determined by the change in wave speed and the initial direction of wave propagation relative to the direction of change in speed. Optical prisms and lenses use refraction to redirect light, as does the human eye. The refractive index of materials varies with the wavelength of light, and thus the angle of the refraction also varies correspondingly. This is called dispersion and allows certain prisms and raindrops in rainbows to divide white light into its constituent spectral colors.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Refraction: Law', 'For light, refraction follows Snell''s law, which states that, for a given pair of media, the ratio of the sines of the angle of incidence', 'Wikipedia: Refraction', 'https://en.wikipedia.org/w/index.php?title=Refraction&oldid=1372828267', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'For light, refraction follows Snell''s law, which states that, for a given pair of media, the ratio of the sines of the angle of incidence');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Refraction: General explanation', 'Refraction involves two related parts, both a result of the wave nature of light: a reduced speed in an optical medium and a change in angle when a wave front crosses between different media at an angle. Light slows as it travels through a medium other than vacuum (such as air, glass or water). This is not because of scattering or absorption. Rather it is because, as an electromagnetic oscillation, light itself causes other electrically charged particles such as electrons, to oscillate. The oscillating electrons emit their own electromagnetic waves which interact with the original light. The resulting combined wave has a lower speed. When light returns to a vacuum and there are no electrons nearby, this slowing effect ends and its speed returns to c. When light enters a slower medium at an angle, one side of the wavefront is slowed before the other. This asymmetrical slowing of the light causes it to change the angle of its travel. Once light is within the new medium with constant properties, it travels in a straight line again.', 'Wikipedia: Refraction', 'https://en.wikipedia.org/w/index.php?title=Refraction&oldid=1372828267', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Refraction involves two related parts, both a result of the wave nature of light: a reduced speed in an optical medium and a change in angle when a wave front crosses between different media at an angle. Light slows as it travels through a medium other than vacuum (such as air, glass or water). This is not because of scattering or absorption. Rather it is because, as an electromagnetic oscillation, light itself causes other electrically charged particles such as electrons, to oscillate. The oscillating electrons emit their own electromagnetic waves which interact with the original light. The resulting combined wave has a lower speed. When light returns to a vacuum and there are no electrons nearby, this slowing effect ends and its speed returns to c. When light enters a slower medium at an angle, one side of the wavefront is slowed before the other. This asymmetrical slowing of the light causes it to change the angle of its travel. Once light is within the new medium with constant properties, it travels in a straight line again.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Refraction: Slowing of light', 'As described above, the speed of light is slower in a medium other than vacuum. This slowing applies to any medium such as air, water, or glass, and is responsible for phenomena such as refraction. On the other side of the medium its speed will again be the speed of light in vacuum, c. A correct explanation rests on light''s nature as an electromagnetic wave. Because light is an oscillating electrical/magnetic wave, light traveling in a medium causes the electrically charged electrons of the material to also oscillate. (The material''s protons also oscillate but as they are around 2000 times more massive, their movement and therefore their effect, is far smaller). A moving electrical charge emits electromagnetic waves of its own. The electromagnetic waves emitted by the oscillating electrons interact with the electromagnetic waves that make up the original light, similar to water waves on a pond, a process known as constructive interference. When two waves interfere in this way, the resulting "combined" wave may have wave packets that pass an observer at a slower rate. The light has effectively been slowed. When the light leaves the material, this interaction with electrons no longer happens, and therefore the wave packet rate (and therefore its speed) return to normal.', 'Wikipedia: Refraction', 'https://en.wikipedia.org/w/index.php?title=Refraction&oldid=1372828267', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'As described above, the speed of light is slower in a medium other than vacuum. This slowing applies to any medium such as air, water, or glass, and is responsible for phenomena such as refraction. On the other side of the medium its speed will again be the speed of light in vacuum, c. A correct explanation rests on light''s nature as an electromagnetic wave. Because light is an oscillating electrical/magnetic wave, light traveling in a medium causes the electrically charged electrons of the material to also oscillate. (The material''s protons also oscillate but as they are around 2000 times more massive, their movement and therefore their effect, is far smaller). A moving electrical charge emits electromagnetic waves of its own. The electromagnetic waves emitted by the oscillating electrons interact with the electromagnetic waves that make up the original light, similar to water waves on a pond, a process known as constructive interference. When two waves interfere in this way, the resulting "combined" wave may have wave packets that pass an observer at a slower rate. The light has effectively been slowed. When the light leaves the material, this interaction with electrons no longer happens, and therefore the wave packet rate (and therefore its speed) return to normal.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Refraction: Bending of light', 'Consider a wave going from one material to another where its speed is slower as in the figure. If it reaches the interface between the materials at an angle one side of the wave will reach the second material first, and therefore slow down earlier. With one side of the wave going slower the whole wave will pivot towards that side. This is why a wave will bend away from the surface or toward the normal when going into a slower material. In the opposite case of a wave reaching a material where the speed is higher, one side of the wave will speed up and the wave will pivot away from that side.', 'Wikipedia: Refraction', 'https://en.wikipedia.org/w/index.php?title=Refraction&oldid=1372828267', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Consider a wave going from one material to another where its speed is slower as in the figure. If it reaches the interface between the materials at an angle one side of the wave will reach the second material first, and therefore slow down earlier. With one side of the wave going slower the whole wave will pivot towards that side. This is why a wave will bend away from the surface or toward the normal when going into a slower material. In the opposite case of a wave reaching a material where the speed is higher, one side of the wave will speed up and the wave will pivot away from that side.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Refraction: Bending of light', 'Another way of understanding the same thing is to consider the change in wavelength at the interface. When the wave goes from one material to another where the wave has a different speed v, the frequency f of the wave will stay the same, but the distance between wavefronts or wavelength λ = v/f will change. If the speed is decreased, such as in the figure to the right, the wavelength will also decrease. With an angle between the wave fronts and the interface and change in distance between the wave fronts the angle must change over the interface to keep the wave fronts intact. From these considerations the relationship between the angle of incidence θ1, angle of transmission θ2 and the wave speeds v1 and v2 in the two materials can be derived. This is the law of refraction or Snell''s law and can be written as The phenomenon of refraction can in a more fundamental way be derived from the 2 or 3-dimensional wave equation. The boundary condition at the interface will then require the tangential component of the wave vector to be identical on the two sides of the interface. Since the magnitude of the wave vector depend on the wave speed this requires a change in direction of the wave vector.', 'Wikipedia: Refraction', 'https://en.wikipedia.org/w/index.php?title=Refraction&oldid=1372828267', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Another way of understanding the same thing is to consider the change in wavelength at the interface. When the wave goes from one material to another where the wave has a different speed v, the frequency f of the wave will stay the same, but the distance between wavefronts or wavelength λ = v/f will change. If the speed is decreased, such as in the figure to the right, the wavelength will also decrease. With an angle between the wave fronts and the interface and change in distance between the wave fronts the angle must change over the interface to keep the wave fronts intact. From these considerations the relationship between the angle of incidence θ1, angle of transmission θ2 and the wave speeds v1 and v2 in the two materials can be derived. This is the law of refraction or Snell''s law and can be written as The phenomenon of refraction can in a more fundamental way be derived from the 2 or 3-dimensional wave equation. The boundary condition at the interface will then require the tangential component of the wave vector to be identical on the two sides of the interface. Since the magnitude of the wave vector depend on the wave speed this requires a change in direction of the wave vector.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Refraction: Bending of light', 'The relevant wave speed in the discussion above is the phase velocity of the wave. This is typically close to the group velocity which can be seen as the truer speed of a wave, but when they differ it is important to use the phase velocity in all calculations relating to refraction. A wave traveling perpendicular to a boundary, i.e. having its wavefronts parallel to the boundary, will not change direction even if the speed of the wave changes.', 'Wikipedia: Refraction', 'https://en.wikipedia.org/w/index.php?title=Refraction&oldid=1372828267', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'The relevant wave speed in the discussion above is the phase velocity of the wave. This is typically close to the group velocity which can be seen as the truer speed of a wave, but when they differ it is important to use the phase velocity in all calculations relating to refraction. A wave traveling perpendicular to a boundary, i.e. having its wavefronts parallel to the boundary, will not change direction even if the speed of the wave changes.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Refraction: Dispersion of light', 'Refraction is also responsible for rainbows and for the splitting of white light into a rainbow-spectrum as it passes through a glass prism. Glass and water have higher refractive indices than air. When a beam of white light passes from air into a material having an index of refraction that varies with frequency (and wavelength), a phenomenon known as dispersion occurs, in which different coloured components of the white light are refracted at different angles, i.e., they bend by different amounts at the interface, so that they become separated. The different colors correspond to different frequencies and different wavelengths.', 'Wikipedia: Refraction', 'https://en.wikipedia.org/w/index.php?title=Refraction&oldid=1372828267', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Refraction is also responsible for rainbows and for the splitting of white light into a rainbow-spectrum as it passes through a glass prism. Glass and water have higher refractive indices than air. When a beam of white light passes from air into a material having an index of refraction that varies with frequency (and wavelength), a phenomenon known as dispersion occurs, in which different coloured components of the white light are refracted at different angles, i.e., they bend by different amounts at the interface, so that they become separated. The different colors correspond to different frequencies and different wavelengths.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Lens', 'A lens is a transmissive optical device that focuses or disperses a light beam by means of refraction. A simple lens consists of a single piece of transparent material, while a compound lens consists of several simple lenses (elements), usually arranged along a common axis. Lenses are made from materials such as glass or plastic and are ground, polished, or molded to the required shape. A lens can focus light to form an image, unlike a prism, which refracts light without focusing. Devices that similarly focus or disperse waves and radiation other than visible light are also called "lenses", such as microwave lenses, electron lenses, acoustic lenses, or explosive lenses. Lenses are used in various imaging devices such as telescopes, binoculars, and cameras. They are also used as visual aids in glasses to correct defects of vision such as myopia and hypermetropia.', 'Wikipedia: Lens', 'https://en.wikipedia.org/w/index.php?title=Lens&oldid=1372120088', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'A lens is a transmissive optical device that focuses or disperses a light beam by means of refraction. A simple lens consists of a single piece of transparent material, while a compound lens consists of several simple lenses (elements), usually arranged along a common axis. Lenses are made from materials such as glass or plastic and are ground, polished, or molded to the required shape. A lens can focus light to form an image, unlike a prism, which refracts light without focusing. Devices that similarly focus or disperse waves and radiation other than visible light are also called "lenses", such as microwave lenses, electron lenses, acoustic lenses, or explosive lenses. Lenses are used in various imaging devices such as telescopes, binoculars, and cameras. They are also used as visual aids in glasses to correct defects of vision such as myopia and hypermetropia.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Lens: Construction of simple lenses', 'Most lenses are spherical lenses: their two surfaces are parts of the surfaces of spheres. Each surface can be convex (bulging outwards from the lens), concave (depressed into the lens), or planar (flat). The line joining the centres of the spheres making up the lens surfaces is called the axis of the lens. Typically the lens axis passes through the physical centre of the lens, because of the way they are manufactured. Lenses may be cut or ground after manufacturing to give them a different shape or size. The lens axis may then not pass through the physical centre of the lens. Toric or sphero-cylindrical lenses have surfaces with two different radii of curvature in two orthogonal planes. They have a different focal power in different meridians. This forms an astigmatic lens. An example is eyeglass lenses that are used to correct astigmatism in someone''s eye.', 'Wikipedia: Lens', 'https://en.wikipedia.org/w/index.php?title=Lens&oldid=1372120088', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Most lenses are spherical lenses: their two surfaces are parts of the surfaces of spheres. Each surface can be convex (bulging outwards from the lens), concave (depressed into the lens), or planar (flat). The line joining the centres of the spheres making up the lens surfaces is called the axis of the lens. Typically the lens axis passes through the physical centre of the lens, because of the way they are manufactured. Lenses may be cut or ground after manufacturing to give them a different shape or size. The lens axis may then not pass through the physical centre of the lens. Toric or sphero-cylindrical lenses have surfaces with two different radii of curvature in two orthogonal planes. They have a different focal power in different meridians. This forms an astigmatic lens. An example is eyeglass lenses that are used to correct astigmatism in someone''s eye.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Lens: Types of simple lenses', 'Lenses are classified by the curvature of the two optical surfaces. A lens is biconvex (or double convex, or just convex) if both surfaces are convex. If both surfaces have the same radius of curvature, the lens is equiconvex. A lens with two concave surfaces is biconcave (or just concave). If one of the surfaces is flat, the lens is plano-convex or plano-concave depending on the curvature of the other surface. A lens with one convex and one concave side is convex-concave or meniscus. Convex-concave lenses are most commonly used in corrective lenses, since the shape minimizes some aberrations. For a biconvex or plano-convex lens in a lower-index medium, a collimated beam of light passing through the lens converges to a spot (a focus) behind the lens. In this case, the lens is called a positive or converging lens. For a thin lens in air, the distance from the lens to the spot is the focal length of the lens, which is commonly represented by f in diagrams and equations. An extended hemispherical lens is a special type of plano-convex lens, in which the lens''s curved surface is a full hemisphere and the lens is much thicker than the radius of curvature.', 'Wikipedia: Lens', 'https://en.wikipedia.org/w/index.php?title=Lens&oldid=1372120088', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Lenses are classified by the curvature of the two optical surfaces. A lens is biconvex (or double convex, or just convex) if both surfaces are convex. If both surfaces have the same radius of curvature, the lens is equiconvex. A lens with two concave surfaces is biconcave (or just concave). If one of the surfaces is flat, the lens is plano-convex or plano-concave depending on the curvature of the other surface. A lens with one convex and one concave side is convex-concave or meniscus. Convex-concave lenses are most commonly used in corrective lenses, since the shape minimizes some aberrations. For a biconvex or plano-convex lens in a lower-index medium, a collimated beam of light passing through the lens converges to a spot (a focus) behind the lens. In this case, the lens is called a positive or converging lens. For a thin lens in air, the distance from the lens to the spot is the focal length of the lens, which is commonly represented by f in diagrams and equations. An extended hemispherical lens is a special type of plano-convex lens, in which the lens''s curved surface is a full hemisphere and the lens is much thicker than the radius of curvature.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Lens: Types of simple lenses', 'Another extreme case of a thick convex lens is a ball lens, whose shape is completely round. When used in novelty photography it is often called a "lensball". A ball-shaped lens has the advantage of being omnidirectional, but for most optical glass types, its focal point lies close to the ball''s surface. Because of the ball''s curvature extremes compared to the lens size, optical aberration is much worse than thin lenses, with the notable exception of chromatic aberration. For a biconcave or plano-concave lens in a lower-index medium, a collimated beam of light passing through the lens is diverged (spread); the lens is thus called a negative or diverging lens. The beam, after passing through the lens, appears to emanate from a particular point on the axis in front of the lens. For a thin lens in air, the distance from this point to the lens is the focal length, though it is negative with respect to the focal length of a converging lens. The behavior reverses when a lens is placed in a medium with higher refractive index than the material of the lens. In this case a biconvex or plano-convex lens diverges light, and a biconcave or plano-concave one converges it.', 'Wikipedia: Lens', 'https://en.wikipedia.org/w/index.php?title=Lens&oldid=1372120088', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Another extreme case of a thick convex lens is a ball lens, whose shape is completely round. When used in novelty photography it is often called a "lensball". A ball-shaped lens has the advantage of being omnidirectional, but for most optical glass types, its focal point lies close to the ball''s surface. Because of the ball''s curvature extremes compared to the lens size, optical aberration is much worse than thin lenses, with the notable exception of chromatic aberration. For a biconcave or plano-concave lens in a lower-index medium, a collimated beam of light passing through the lens is diverged (spread); the lens is thus called a negative or diverging lens. The beam, after passing through the lens, appears to emanate from a particular point on the axis in front of the lens. For a thin lens in air, the distance from this point to the lens is the focal length, though it is negative with respect to the focal length of a converging lens. The behavior reverses when a lens is placed in a medium with higher refractive index than the material of the lens. In this case a biconvex or plano-convex lens diverges light, and a biconcave or plano-concave one converges it.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Lens: Types of simple lenses', 'Convex-concave (meniscus) lenses can be either positive or negative, depending on the relative curvatures of the two surfaces. A negative meniscus lens has a steeper concave surface (with a shorter radius than the convex surface) and is thinner at the centre than at the periphery. Conversely, a positive meniscus lens has a steeper convex surface (with a shorter radius than the concave surface) and is thicker at the centre than at the periphery. An ideal thin lens with two surfaces of equal curvature (also equal in the sign) would have zero optical power (as its focal length becomes infinity as shown in the lensmaker''s equation), meaning that it would neither converge nor diverge light. All real lenses have a nonzero thickness, however, which makes a real lens with identical curved surfaces slightly positive. To obtain exactly zero optical power, a meniscus lens must have slightly unequal curvatures to account for the effect of the lens'' thickness.', 'Wikipedia: Lens', 'https://en.wikipedia.org/w/index.php?title=Lens&oldid=1372120088', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'Convex-concave (meniscus) lenses can be either positive or negative, depending on the relative curvatures of the two surfaces. A negative meniscus lens has a steeper concave surface (with a shorter radius than the convex surface) and is thinner at the centre than at the periphery. Conversely, a positive meniscus lens has a steeper convex surface (with a shorter radius than the concave surface) and is thicker at the centre than at the periphery. An ideal thin lens with two surfaces of equal curvature (also equal in the sign) would have zero optical power (as its focal length becomes infinity as shown in the lensmaker''s equation), meaning that it would neither converge nor diverge light. All real lenses have a nonzero thickness, however, which makes a real lens with identical curved surfaces slightly positive. To obtain exactly zero optical power, a meniscus lens must have slightly unequal curvatures to account for the effect of the lens'' thickness.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Lens: For a spherical surface', 'For a single refraction for a circular boundary, the relation between object and its image in the paraxial approximation is given by where R is the radius of the spherical surface, n2 is the refractive index of the material of the surface, n1 is the refractive index of medium (the medium other than the spherical surface material), is the on-axis (on the optical axis) object distance from the line perpendicular to the axis toward the refraction point on the surface (which height is h), and is the on-axis image distance from the line. Due to paraxial approximation where the line of h is close to the vertex of the spherical surface meeting the optical axis on the left, toward the right infinity leads to the first or object focal length toward the left infinity leads to the second or image focal length Applying this equation on the two spherical surfaces of a lens and approximating the lens thickness to zero (so a thin lens) leads to the lensmaker''s formula.', 'Wikipedia: Lens', 'https://en.wikipedia.org/w/index.php?title=Lens&oldid=1372120088', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'waves-sound-light' and body = 'For a single refraction for a circular boundary, the relation between object and its image in the paraxial approximation is given by where R is the radius of the spherical surface, n2 is the refractive index of the material of the surface, n1 is the refractive index of medium (the medium other than the spherical surface material), is the on-axis (on the optical axis) object distance from the line perpendicular to the axis toward the refraction point on the surface (which height is h), and is the on-axis image distance from the line. Due to paraxial approximation where the line of h is close to the vertex of the spherical surface meeting the optical axis on the left, toward the right infinity leads to the first or object focal length toward the left infinity leads to the second or image focal length Applying this equation on the two spherical surfaces of a lens and approximating the lens thickness to zero (so a thin lens) leads to the lensmaker''s formula.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'waves-sound-light', 'Lens: Derivation', ', and using small angle approximation (paraxial approximation) and eliminating i, r, and θ,', 'Wikipedia: Lens', 'https://en.wikipedia.org/w/index.php?title=Lens&oldid=1372120088', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
